// 1. 观察者模式基础结构
public interface Subject {
    void registerObserver(Observer observer);
    void removeObserver(Observer observer);
    void notifyObservers();
}
public interface Observer {
    void update(String message);
}
public class ConcreteSubject implements Subject {
    private List<Observer> observers = new ArrayList<>();
    private String state;

    @Override
    public void registerObserver(Observer observer) {
        observers.add(observer);
    }

    @Override
    public void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    @Override
    public void notifyObservers() {
        for (Observer observer : observers) {
            observer.update(state);
        }
    }

    public void setState(String state) {
        this.state = state;
        notifyObservers();
    }
}

// 2. Spring事件机制
// 定义事件
public class OrderEvent extends ApplicationEvent {
    private String orderId;

    public OrderEvent(Object source, String orderId) {
        super(source);
        this.orderId = orderId;
    }
}
// 发布事件
@Component
public class OrderService {
    @Autowired
    private ApplicationEventPublisher publisher;

    public void createOrder(String orderId) {
        // 创建订单逻辑
        publisher.publishEvent(new OrderEvent(this, orderId));
    }
}
// 监听事件
@Component
public class OrderListener implements ApplicationListener<OrderEvent> {
    @Override
    public void onApplicationEvent(OrderEvent event) {
        System.out.println("订单创建: " + event.getOrderId());
    }
}

// 3. @EventListener注解
@Component
public class AnnotationListener {
    @EventListener
    public void handleOrderEvent(OrderEvent event) {
        System.out.println("注解监听: " + event.getOrderId());
    }

    @EventListener(condition = "#event.orderId.startsWith('VIP')")
    public void handleVipOrder(OrderEvent event) {
        System.out.println("VIP订单处理");
    }
}

// 4. 异步事件
@Component
public class AsyncEventListener {
    @Async
    @EventListener
    public void handleAsync(OrderEvent event) {
        // 异步处理
    }
}
